WITH filtered AS (SELECT *, CONCAT_WS(',', account_type, status) account_type_status_key FROM accounts WHERE opened_date BETWEEN '2024-05-01' AND '2024-11-01'), eligible AS (SELECT s.* FROM filtered s WHERE NOT EXISTS (SELECT 1 FROM transactions ch WHERE ch.account_id = s.id AND ch.txn_time < s.opened_date)), with_dims AS (SELECT src.*, b.segment, b.email FROM eligible src INNER JOIN customers b ON src.customer_id = b.id), joined AS (SELECT e.*, c.name, c.city, c.age FROM with_dims e LEFT JOIN customers c ON e.customer_id = c.id WHERE c.credit_limit >= 13800) SELECT d.country, e.status, COUNT(*) AS rows_total, MAX(e.balance) AS max_balance, GROUPING_ID() AS level_id FROM joined e INNER JOIN customers d ON e.customer_id = d.id GROUP BY GROUPING SETS ((d.country, e.status), (d.country), ());
